// Extrae el texto de las primeras paginas de un PDF usando pdf.js (cargado en el
// index.html). Se manda como TEXTO PLANO a la IA en vez de como documento PDF nativo,
// para evitar el limite de 100 paginas por peticion de la API de Claude con PDFs (el
// ESS puede tener varios cientos de paginas; los datos generales que necesitamos aqui
// estan casi siempre en la portada y en las primeras paginas).
// Extrae texto de un PDF preservando los saltos de linea reales (comparando la
// posicion vertical de cada fragmento de texto), en vez de unirlo todo en un bloque
// continuo. Esto es necesario para poder detectar despues titulos de apartado por
// patron de linea (numero + texto en mayusculas solo en esa linea).
var extraerTextoPDF = async function(file, maxPaginas) {
  var buf = await file.arrayBuffer();
  var pdf = await window.pdfjsLib.getDocument({data:buf}).promise;
  var n = Math.min(pdf.numPages, maxPaginas);
  var texto = "";
  for (var i=1;i<=n;i++) {
    var page = await pdf.getPage(i);
    var content = await page.getTextContent();
    var lastY = null;
    var linea = "";
    for (var j=0;j<content.items.length;j++) {
      var it = content.items[j];
      var y = it.transform ? it.transform[5] : null;
      if (lastY !== null && y !== null && Math.abs(y - lastY) > 2) {
        texto += linea.trim() + "\n";
        linea = "";
      }
      linea += it.str + " ";
      lastY = y;
    }
    texto += linea.trim() + "\n\n";
  }
  return texto;
};

