  var generarRiesgosAnexo = async function(catId, catNombre) {
    setGenAnexoEstado(function(p){return Object.assign({},p,((function(){var o={};o[catId]="generando";return o;})()));});
    try {
      if (!apiKey) throw new Error("Configura tu clave de Anthropic.");
      var bloque = matchBloqueESS(catNombre);
      var instruccion = bloque
        ? "Estas leyendo el bloque del ESS correspondiente a la unidad de obra \""+bloque.nombre+"\", emparejada con la actividad nueva \""+catNombre+"\". Extrae los riesgos identificados (SOLO los que aparecen en el texto, sin inventar). Para cada uno: cod corto, desc, tipo (Seguridad/Higiene/Ergonomico/Psicosocial), norma si aparece. IMPORTANTE: consolida duplicados en una sola entrada. Responde SOLO JSON sin markdown: [{\"cod\":\"\",\"desc\":\"\",\"tipo\":\"\",\"norma\":\"\"}]"
        : "Eres tecnico de PRL en España. Para la actividad de obra \""+catNombre+"\", lista los riesgos laborales especificos (4-10, los mas relevantes). Para cada uno: cod corto, desc breve, tipo (Seguridad/Higiene/Ergonomico/Psicosocial), normativa española si la conoces con certeza (si no, dejala vacia). Responde SOLO JSON sin markdown: [{\"cod\":\"\",\"desc\":\"\",\"tipo\":\"\",\"norma\":\"\"}]";
      var contexto = bloque ? ("\n\nBLOQUE DEL ESS:\n"+bloque.texto) : "";
      var resp = await fetch("https://api.anthropic.com/v1/messages",{method:"POST",headers:{"Content-Type":"application/json","x-api-key":apiKey,"anthropic-version":"2023-06-01","anthropic-dangerous-direct-browser-access":"true"},body:JSON.stringify({model:"claude-sonnet-4-6",max_tokens:2500,messages:[{role:"user",content:instruccion+contexto}]})});
      var d = await resp.json();
      if (!resp.ok) throw new Error((d.error&&d.error.message)||("Error API ("+resp.status+")"));
      var blq2 = d.content&&d.content.find(function(x){return x.type==="text";});
      var raw = blq2?blq2.text:"[]";
      var s=raw.indexOf("["),e2=raw.lastIndexOf("]");
      var lista = [];
      try { lista=(s>=0&&e2>s)?JSON.parse(raw.slice(s,e2+1)):[];} catch(e){}
      var normDesc = function(s2){ return (s2||"").toLowerCase().trim().replace(/\s+/g," "); };
      setAnexoCategorias(function(prev){ return prev.map(function(c){
        if (c.id!==catId) return c;
        var vistos = c.riesgos.map(function(r){return normDesc(r.desc);});
        var nuevos = [];
        lista.forEach(function(r){
          var n=normDesc(r.desc);
          if(!n||vistos.indexOf(n)!==-1) return;
          vistos.push(n);
          nuevos.push({id:uid(),desc:r.desc,tipo:r.tipo||"Seguridad",cod:r.cod||"ESS",norma:r.norma||"",fuente:bloque?"ess":"ia"});
        });
        return Object.assign({},c,{riesgos:c.riesgos.concat(nuevos)});
      });});
      setGenAnexoEstado(function(p){return Object.assign({},p,((function(){var o={};o[catId]="ok";return o;})()));});
    } catch(err) {
      setGenAnexoEstado(function(p){return Object.assign({},p,((function(){var o={};o[catId]="error";return o;})()));});
    }
  };



